import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.DE5v7xUD.js";var i=JSON.parse(`{"title":"Discover and Diagnose Recon","description":"","frontmatter":{"id":"guide.cli-contract","title":"Discover and Diagnose Recon","describes":["proposal.0003","proposal.0004"]},"headers":[],"relativePath":"guides/cli-contract.md","filePath":"guides/cli-contract.md"}`),a={name:`guides/cli-contract.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="discover-and-diagnose-recon" tabindex="-1">Discover and Diagnose Recon <a class="header-anchor" href="#discover-and-diagnose-recon" aria-label="Permalink to “Discover and Diagnose Recon”">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><p>Recon describes its commands through help and a machine-readable schema. <code>recon context</code> reports the installed executable&#39;s identity, permissions, and host capabilities without requesting any permission or touching a target application.</p><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to “How to use it”">​</a></h2><p>Run <code>recon</code>, <code>recon --help</code>, <code>recon -h</code>, or <code>recon help</code> for orientation. Help lists every command and the discovery commands. For a group or command, append <code>--help</code> or <code>-h</code>, or put its path after <code>recon help</code>. Help succeeds on standard output even when other arguments are malformed. Help has no terminal colors and is identical when redirected.</p><p>Run <code>recon --version</code> for the crate version and, when available at build time, the short Git commit and its author date. A build without eligible Git metadata prints only the version. <code>-v</code> and <code>-V</code> are usage errors.</p><p>The version suffix and <code>context.recon.commit</code> report the checkout&#39;s <code>HEAD</code> baseline when the Git root matches this workspace and the committed <code>crates/recon/Cargo.toml</code> names package <code>recon</code>. Missing, malformed, or nonmatching metadata is omitted. Dirty dependency/version edits and linked worktrees keep that baseline. A same-name archive overlaid on another checkout can also qualify: this name-based check cannot attest to source origin or byte-for-byte correspondence. No remote or history allowlist is consulted.</p><p>Ambient build-environment metadata cannot supply a missing commit or override the eligible checkout&#39;s baseline.</p><p>The next build refreshes metadata when <code>HEAD</code> moves or a source archive becomes a checkout. Changes to a linked or separate checkout&#39;s <code>.git</code> locator are also observed.</p><p>Unchanged eligible checkouts remain fresh with the same build inputs. When the workspace&#39;s <code>.git</code> locator is absent, Cargo reruns the metadata build script on each build so repository creation is detected; this is a build-time cost for archives.</p><p><code>recon schema</code> returns the command index in stable order, with effects, supported hosts, and the complete error contract. <code>recon schema &lt;command&gt;</code> returns that command&#39;s arguments, options, constraints, defaults, effects, permissions, supported hosts, output JSON Schema, and possible error codes. <code>recon schema schema</code> and <code>recon schema context</code> describe the discovery commands themselves. An unknown schema path is an <code>INVALID_ARGUMENT</code> error listing accepted paths.</p><p>Output schemas use JSON Schema 2020-12. Each is self-contained; local <code>$defs</code> resolve every reference without a network request. Objects Recon controls reject unknown properties. The schemas describe serialized output, including optional truncation markers and the repeated and failed node forms of an accessibility tree.</p><p>Options use long names. Flags take no value; value-taking options take exactly one. Options may precede or follow the target. Repeated or unknown options, missing values, a value beginning with a hyphen, and extra positionals are errors. Numbers contain ASCII decimal digits only, within the unsigned 32-bit range; <code>--pid</code> must exceed zero. A group alone requires an operation. Only an empty invocation shows top-level help automatically.</p><h2 id="read-the-execution-context" tabindex="-1">Read the execution context <a class="header-anchor" href="#read-the-execution-context" aria-label="Permalink to “Read the execution context”">​</a></h2><p><code>recon context</code> returns <code>recon</code> with version, full build commit or <code>null</code>, and the canonical absolute executable path. <code>host</code> gives the compiled target OS and architecture; its version is the structured macOS product version or <code>null</code> on other hosts. <code>macos</code> is <code>null</code> outside macOS.</p><p>On macOS, the report includes code-signing identifier and team, signed and ad-hoc flags, whether Recon is responsible for its own privacy identity, preflight results for Screen Recording and Accessibility, the private interfaces it uses, and application-discovery availability. Permission entries include the System Settings pane that grants each permission. An identity failure before spawning is reported with a reason and <code>granted: null</code> for both permissions. Those grants are unknown; the launcher&#39;s permissions cannot answer the question.</p><p>Signing facts describe the running process even if its executable file has been replaced. Recon reads only its own kernel signing status and, when signed, its own code-directory hash. A successful status query reporting no signature produces <code>signed: false</code>, null identifier and team, and <code>adHoc: false</code>. For signed code, the selected public signing metadata must match that kernel hash before Recon reports its identifier, team, or ad-hoc flag. <code>signed: true</code> carries no validity or trust guarantee.</p><p>The <code>code-signing-query</code> capability names the required <code>csops</code> symbol. A missing symbol, failed status or hash query, unreadable required metadata, or mismatched selected hash produces <code>INTERNAL</code> with exit 1. These failures cannot be reported as unsigned. No raw status or hash is included in the report.</p><p>Context re-executes when necessary to report Recon&#39;s own grants. It never asks macOS to request a permission or shows a permission dialog. Missing permissions and other missing private interfaces remain reportable context facts. Discovery availability measures Recon&#39;s own Spotlight query and indexed application count, rather than Spotlight&#39;s system-wide configuration. Ad-hoc builds lose grants on rebuild; this report does not change signing or grants.</p><h2 id="read-a-failure" tabindex="-1">Read a failure <a class="header-anchor" href="#read-a-failure" aria-label="Permalink to “Read a failure”">​</a></h2><p>With functioning output streams, every failure produces exactly one compact JSON object on one newline-terminated line of standard error, with no prose prefix and no success output. <code>error.code</code> classifies the failure, <code>message</code> explains it, <code>retryable</code> says whether repeating the identical command can succeed, <code>command</code> gives the resolved path or <code>null</code>, and <code>details</code> provides recovery data or <code>null</code> when there is none. Use codes and details rather than matching English messages.</p><p>Exit status is 0 on success, 2 for <code>INVALID_ARGUMENT</code> failures detectable from the command line alone, and 1 for runtime failures. Signals retain their normal shell behavior, including when Recon re-executes.</p><p>When Recon re-executes, the parent withholds both child output streams until it has successfully waited for the child. It drains both streams concurrently, so large results cannot deadlock against full pipes. After a successful wait and successful output writes, each stream&#39;s bytes and the child&#39;s exit status are preserved. A genuine wait failure discards all child output and produces only <code>IDENTITY_UNAVAILABLE</code> with <code>details.stage: &quot;wait&quot;</code>, exit 1, and empty standard output. This applies to <code>context</code> too: a post-spawn wait failure never produces a fallback context report.</p><p>A failing output sink cannot provide atomic delivery: bytes it already accepted cannot be recalled. If stdout delivery fails, Recon stops forwarding the remaining child streams and exits 1 with at most one best-effort <code>INTERNAL</code> diagnostic on untouched stderr. If forwarding child stderr fails, Recon exits 1 without appending another diagnostic or retrying that stream.</p><p>If an already-classified error cannot be written or flushed, Recon stops the delivery attempt without a panic or second diagnostic. Its original classification remains: usage errors exit 2, and runtime errors exit 1. A broken stderr may receive only a prefix or no diagnostic.</p><p>For an invalid argument, inspect <code>argument</code>, <code>value</code>, <code>expected</code>, and <code>accepted</code>. For <code>AMBIGUOUS_TARGET</code>, choose one of <code>candidates</code> by bundle path; for <code>AMBIGUOUS_INSTANCE</code>, choose a listed process ID. <code>PERMISSION_DENIED</code> gives each missing permission&#39;s <code>settingsPane</code>, the executable path, and whether it is ad-hoc signed. <code>IDENTITY_UNAVAILABLE</code> identifies the failed re-execution stage. <code>TIMEOUT</code>, <code>DISCOVERY_UNAVAILABLE</code>, and <code>CAPTURE_FAILED</code> are retryable. Other codes require changing arguments, application state, permissions, or installation conditions first. The schema index publishes every stable code and its exit status.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to “Worked example”">​</a></h2><p>With <code>recon</code> on your path, learn the tree command without inspecting an application:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">recon</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --help</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">recon</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ui</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ax</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> tree</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --help</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">recon</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --version</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">recon</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> schema</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">recon</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> schema</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ui</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ax</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> tree</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">recon</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> context</span></span></code></pre></div><p>Each succeeds on standard output. The first three print text; the remaining commands print one JSON object each. To inspect a usage error without consulting macOS:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">recon</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ui</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> ax</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> tree</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> Calculator</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --window</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> abc</span></span></code></pre></div><p>This exits 2, leaves standard output empty, and emits an <code>INVALID_ARGUMENT</code> object whose details identify <code>--window</code>, value <code>abc</code>, and the decimal window-ID requirement.</p><h2 id="limits-and-edge-cases" tabindex="-1">Limits and edge cases <a class="header-anchor" href="#limits-and-edge-cases" aria-label="Permalink to “Limits and edge cases”">​</a></h2><ul><li>The schema describes this binary, including its supported hosts. Capability commands still fail with <code>UNSUPPORTED_HOST</code> outside macOS; help, schema, and context work everywhere.</li><li><code>context</code> reads state only. Existing <code>ui</code> commands still request missing permissions before returning <code>PERMISSION_DENIED</code>.</li><li><code>app launch</code> can activate an application. <code>ui screenshot</code> writes a new file. Other commands are read-only; schema <code>effects</code> records these distinctions.</li><li><code>schema</code> reads nothing outside Recon and needs no permissions. Context probes the host but launches no application.</li></ul>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};